#!/usr/bin/env node
/**
 * Capture the README screenshots from the real, built studio.
 *
 * Reproducible on purpose: the images in `docs/screenshots/` are generated by
 * this script against the production build with a fixed seed, so they can never
 * show a state the application does not actually produce. Regenerate with:
 *
 *   pnpm build && pnpm screenshots
 *
 * It starts its own static server on a spare port so it does not collide with
 * a dev server you may have running.
 */
import { spawn } from 'node:child_process';
import { mkdirSync } from 'node:fs';
import { chromium } from '@playwright/test';

const ROOT = new URL('..', import.meta.url).pathname;
const OUT = `${ROOT}docs/screenshots`;
const PORT = 3149;
const BASE = `http://127.0.0.1:${PORT}`;

mkdirSync(OUT, { recursive: true });

const server = spawn('npx', ['--yes', 'serve', 'apps/studio/out', '-l', String(PORT)], {
  cwd: ROOT,
  stdio: 'ignore',
});

/** Poll until the static server answers, so the first navigation never races. */
async function waitForServer(timeoutMs = 30_000) {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    try {
      const response = await fetch(BASE);
      if (response.ok) return;
    } catch {
      // not up yet
    }
    if (Date.now() > deadline) throw new Error(`${BASE} did not start within ${timeoutMs}ms`);
    await new Promise((resolve) => setTimeout(resolve, 300));
  }
}

const shots = [];

try {
  await waitForServer();
  const browser = await chromium.launch();

  // --- desktop workspace ---
  {
    const page = await browser.newPage({
      viewport: { width: 1600, height: 950 },
      deviceScaleFactor: 2,
    });
    await page.goto(BASE);
    await page.locator('.monaco-editor').first().waitFor({ timeout: 60_000 });

    // Step twice to the Bell state, then run, so the capture shows real numbers.
    const step = page.getByRole('button', { name: 'Step', exact: true });
    await step.click();
    await step.click();
    await page.getByRole('button', { name: 'Run', exact: true }).click();
    await page.waitForTimeout(700);

    await page.screenshot({ path: `${OUT}/studio.png` });
    shots.push('studio.png');

    // --- compiler inspector, IR view ---
    await page.getByRole('tab', { name: /^IR/ }).click();
    await page.waitForTimeout(300);
    await page.getByTestId('panel-compiler').screenshot({ path: `${OUT}/compiler-ir.png` });
    shots.push('compiler-ir.png');

    // --- the optimiser's pass report ---
    await page.locator('#qf-example').selectOption('optimisable');
    await page.getByRole('checkbox', { name: 'Optimise' }).check();
    await page.waitForTimeout(500);
    await page.getByRole('tab', { name: 'Passes' }).click();
    await page.waitForTimeout(300);
    await page.getByTestId('panel-compiler').screenshot({ path: `${OUT}/optimiser.png` });
    shots.push('optimiser.png');

    // --- debugger mid-measurement ---
    await page.locator('#qf-example').selectOption('bell');
    await page.waitForTimeout(500);
    await page.getByRole('button', { name: 'To end' }).click();
    await page.waitForTimeout(400);
    await page.getByTestId('panel-debugger').screenshot({ path: `${OUT}/debugger.png` });
    shots.push('debugger.png');

    await page.close();
  }

  // --- mobile ---
  {
    const page = await browser.newPage({
      viewport: { width: 390, height: 844 },
      deviceScaleFactor: 2,
    });
    await page.goto(BASE);
    await page.locator('.monaco-editor').first().waitFor({ timeout: 60_000 });
    await page.getByRole('tab', { name: /^Circuit/ }).click();
    await page.waitForTimeout(500);
    await page.screenshot({ path: `${OUT}/mobile.png` });
    shots.push('mobile.png');
    await page.close();
  }

  await browser.close();
  console.log(`Captured ${shots.length} screenshots into docs/screenshots:`);
  for (const shot of shots) console.log(`  ${shot}`);
} finally {
  server.kill();
}
